# A meta refresh content value looks like: "0;url=javascript:alert(1)" or
# "0; url=..." or just "5" (a delay with no url).  We only need to check the
# url= part.
_META_URL_RE = re.compile(r"(?i)url\s*=\s*(.+)")

def _is_safe_meta_refresh(content):
    """Return True if the meta refresh content has no dangerous url."""
    m = _META_URL_RE.search(content)
    if not m:
        # No url= part: just a delay.  Safe.
        return True
    url = m.group(1).strip()
    # Strip a trailing quote if present.
    if url and url[0] in "'\"" and url[-1] == url[0]:
        url = url[1:-1]
    return _is_safe_url(url)

